"""Plain-text absence notices for parents."""

from rosterkit.models import Student


def absence_notice(student: Student, marks: list) -> str:
    """Build a short notice listing the days a student missed."""
    foreign = [mark for mark in marks
               if mark.student_id != student.student_id]
    if foreign:
        raise ValueError("marks belong to another student")
    days = sorted(mark.day for mark in marks
                  if mark.status == "absent")
    if not days:
        raise ValueError("no absences to report")
    name = f"{student.first_name} {student.last_name}"
    word = "day" if len(days) == 1 else "days"
    dates = ", ".join(when.isoformat() for when in days)
    return (
        f"Dear parent or guardian, {name} missed "
        f"{len(days)} {word} of school: {dates}."
    )
